changeSet.sql:
CREATE TABLE validation_report ( validation_key uuid NOT NULL, attempt integer NOT NULL, report_type varchar(255) NOT NULL, report text NOT NULL, created timestamp with time zone NOT NULL DEFAULT now(), modified timestamp with time zone NOT NULL DEFAULT now(),
CONSTRAINT pk_validation_report PRIMARY KEY (validation_key, attempt, report_type),
CONSTRAINT fk_validation_report_validation FOREIGN KEY (validation_key) REFERENCES validation (key) ON DELETE CASCADE );
